using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class RealQwen216Tests {
 public static int Main(string[] args){try{string root=Path.GetDirectoryName(typeof(AiTimeline).Assembly.Location),mode=args.Length>0?args[0]:"translate";var ai=new LocalAi(root,"cpu");string validation=Path.Combine(root,"validation");Directory.CreateDirectory(validation);
  if(mode=="repair"){
   var source=Path.Combine(root,"source/fixtures/van215/van 6.srt");var cues=Scripts.ParseSrt(File.ReadAllText(source));var p=AiRepairSession.Open(source,cues,Path.Combine(validation,"real-repair-state"),new VoiceSettings{Mode=2},true,"historical-context-only");var row=p.Rows.Single(r=>r.Stage.Cues.First().Id==5);var m=new AiMeasurement{Natural=12.598,After=13.962,Target=14.4,Speed=.9,Tts=12.226,AppPauses=.118,Breaths=.254,NeedsRepair=true,Kind="UNDER DURATION"};string prompt=AiTimeline.Prompt(p,row,m);var raw=ai.Rewrite(prompt,()=>false,s=>Console.WriteLine(s));File.WriteAllText(Path.Combine(validation,"real-qwen-repair-raw.txt"),raw);var candidate=AiTimeline.Candidate(raw,row.Stage.Cues);var meaning=RepairPolicy.Check(row.Stage.Cues,candidate);File.WriteAllText(Path.Combine(validation,"real-qwen-repair.txt"),prompt+"\nRAW:\n"+raw+"\nSemantic: "+meaning.Reason+"\nCandidate TTS NOT MEASURED: selected Steven clone is unavailable in build environment.");if(candidate.Select(c=>c.Text).SequenceEqual(row.Stage.Cues.Select(c=>c.Text)))throw new Exception("Actual Qwen still returned original text.");Console.WriteLine("PASS actual pinned Qwen 4B generated a new parsed candidate; semantic="+(meaning.Rejected?"BLOCKED":meaning.Safe?"SAFE":"NEEDS_REVIEW")+". No cloned TTS success claimed.");return 0;
  }
  var failures=new List<string>();foreach(string name in new[]{"van 4","van 5","van 6"}.Where(n=>args.Length<2||args[1]==n)){var cues=Scripts.ParseSrt(File.ReadAllText(Path.Combine(root,"source/fixtures/van215",name+".srt")));var result=OfflineTranslation.Run(cues,ai,Path.Combine(validation,"real-vi-cache"),()=>false,(n,msg)=>Console.WriteLine(name+" "+n+"% "+msg),Path.Combine(root,"source/fixtures/van215",name+".srt"));string folder=Path.Combine(validation,"real-translations");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,name+".vi.txt"),StableArtifacts.Bilingual(cues,true,false,result).Replace("ĐỐI CHIẾU LỜI CUỐI ĐÃ DÙNG TẠO WAV","ĐỐI CHIẾU DỊCH KIỂM THỬ — CHƯA TẠO WAV GIỌNG THẬT"));if(!result.Complete){failures.Add(name);Console.WriteLine("FAIL TRANSLATION_INCOMPLETE "+name+": "+result.Text.Count+"/"+cues.Count+" verified cues. "+result.Error+"\n"+result.Stack);continue;}Console.WriteLine("PASS offline EN-VI completion (aligned source + real Qwen CPU): "+name+" "+result.Text.Count+"/"+cues.Count+" cues, structure/numeric/model verification; not a TTS/GPU test.");}
  return failures.Count==0?0:1;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
